static uint64_t f2u(float f){
  const float T63 = 9223372036854775808.0f;
  if(!(f >= T63)) return (uint64_t)cvttss2si(f);
  return (uint64_t)cvttss2si(f - T63) + 0x8000000000000000ULL;
}
static uint64_t rup2(uint64_t v){ if(v==0) return 1; if((v&(v-1))==0) return v;
  v--; for(unsigned i=1;i<64;i*=2) v|=v>>i; return v+1; }

/* reserve(count) -> bucket_count */
static uint64_t reserve_bc(uint64_t count){
  float t = ceilf((float)count / 0.9f);
  uint64_t target = f2u(t);
  if(target == 0) return 0;
  return rup2(target);
}
