// 2^63 exactly representable in f32
const P63: f32 = 9_223_372_036_854_775_808.0;

/// x86-64 `cvttss2si` (f32 -> i64, truncate toward zero).
/// Out-of-range or NaN yields the "integer indefinite" value i64::MIN.
#[inline]
fn cvttss2si(f: f32) -> i64 {
    if f.is_nan() { return i64::MIN; }
    let t = f.trunc();
    if t >= P63 || t < -P63 { i64::MIN } else { t as i64 }
}

/// Emulates C++ `static_cast<std::size_t>(f)` as GCC compiles it on x86-64.
/// Rust's `as` saturates, C++ is UB -- this reproduces the hardware result.
#[inline]
fn f32_to_usize(f: f32) -> usize {
    if !(f >= P63) {
        // comiss/jnb: NaN and all negatives take this path too
        cvttss2si(f) as u64 as usize
    } else {
        (cvttss2si(f - P63) as u64).wrapping_add(1u64 << 63) as usize
    }
}

/// tsl::power_of_two_growth_policy::round_up_to_power_of_two -- NON-strict.
#[inline]
fn round_up_to_power_of_two(mut v: usize) -> usize {
    if v == 0 { return 1; }
    if v.is_power_of_two() { return v; }
    v -= 1;
    let mut i = 1u32;
    while i < usize::BITS { v |= v >> i; i *= 2; }
    v + 1
}

/// bucket_count right after `reserve(count)` on a fresh map (max_load_factor 0.9f).
fn reserve_bucket_count(count: usize) -> usize {
    let target = f32_to_usize(((count as f32) / 0.9f32).ceil());
    if target == 0 { 0 } else { round_up_to_power_of_two(target) }
}

/// m_load_threshold = size_type(float(bucket_count) * max_load_factor)
#[inline]
fn load_threshold(bucket_count: usize) -> usize {
    f32_to_usize((bucket_count as f32) * 0.9f32)
}

/// Full program model: map.reserve(count); then insert keys 0..count.
fn simulate(count: i32) -> (usize, usize) {
    let mut bc = reserve_bucket_count(count as isize as usize);
    let n: usize = if count < 0 { 0 } else { count as usize };
    // rehash_on_extreme_load(): checked before each insert, size() runs 0..n-1
    while n > 0 && n - 1 >= load_threshold(bc) {
        bc = if bc == 0 { 1 } else { bc * 2 };
    }
    (n, bc)
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    for a in &args[1..] {
        let n: i64 = a.parse().unwrap();
        let (s, bc) = simulate(n as i32);
        println!("{} {} 0", s, bc);
    }
}
